const $=id=>document.getElementById(id),SESSION='spotify-session-v1',PENDING='spotify-pkce-v1',CLIENT='dock-spotify-client-id-v1',redirect=location.origin+location.pathname;
let auth=null,offset=0,loading=false,searchVersion=0;
try{auth=JSON.parse(sessionStorage.getItem(SESSION)||'null')}catch{}
function status(message){$('account-status').textContent=message}
function controls(){$('spotify-connect').textContent=auth?'Reconnect Spotify':'Connect Spotify';$('spotify-disconnect').hidden=!auth;$('catalog-search').disabled=!auth;$('playlists-refresh').disabled=!auth}
async function tokenRequest(body){const response=await fetch('https://accounts.spotify.com/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(body),signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error('Spotify sign-in failed or expired. Reconnect Spotify.');const data=await response.json();if(typeof data.access_token!=='string')throw Error('Spotify did not return an access token.');return data}
function store(data,client){auth={client,access:data.access_token,refresh:data.refresh_token||auth?.refresh,expires:Date.now()+(Number(data.expires_in)||3600)*1000};sessionStorage.setItem(SESSION,JSON.stringify(auth));controls()}
async function api(path){if(!auth)throw Error('Connect Spotify first.');if(auth.expires<Date.now()+30000){if(!auth.refresh)throw Error('Reconnect Spotify to continue.');store(await tokenRequest({grant_type:'refresh_token',refresh_token:auth.refresh,client_id:auth.client}),auth.client)}const response=await fetch('https://api.spotify.com/v1/'+path,{headers:{Authorization:'Bearer '+auth.access},signal:AbortSignal.timeout(20000)});if(response.status===429)throw Error('Spotify is limiting requests. Wait '+(response.headers.get('Retry-After')||'30')+' seconds.');if(response.status===403)throw Error('Spotify denied access. Check Premium/development-mode eligibility and your app’s user allowlist.');if(!response.ok)throw Error('Spotify could not complete this request ('+response.status+'). Reconnect if needed.');return response.json()}
function rows(root,items){for(const item of items||[]){if(!item)continue;const url=item.external_urls?.spotify;if(typeof url!=='string')continue;const row=document.createElement('button');row.className='catalog-item';const name=document.createElement('strong');name.textContent=item.name||'Untitled';const subtitle=document.createElement('small');subtitle.textContent=item.artists?.map(a=>a.name).join(', ')||item.owner?.display_name||item.type||'Spotify';row.append(name,subtitle);row.onclick=()=>window.dispatchEvent(new CustomEvent('dock-spotify-load',{detail:url}));root.append(row)}}
async function playlists(more=false){if(loading)return;loading=true;$('playlists-refresh').disabled=true;$('playlists-more').disabled=true;try{const next=more?offset+20:0,data=await api('me/playlists?limit=20&offset='+next);if(!auth)return;if(!more)$('account-playlists').replaceChildren();rows($('account-playlists'),data.items);offset=next;$('playlists-more').hidden=!data.next;status(data.items?.length?'Your playlists are ready. Select one to load it.':'No playlists found.')}catch(error){status(error.message)}finally{loading=false;$('playlists-refresh').disabled=!auth;$('playlists-more').disabled=false}}
$('redirect-uri').value=redirect;try{$('client-id').value=localStorage.getItem(CLIENT)||''}catch{}
$('spotify-connect').onclick=()=>$('spotify-setup').showModal();$('setup-close').onclick=()=>$('spotify-setup').close();
$('spotify-auth-form').onsubmit=async event=>{event.preventDefault();try{const client=$('client-id').value.trim();if(!/^[a-f0-9]{32}$/i.test(client))throw Error('Enter your public Spotify Client ID.');const random=()=>Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join(''),verifier=random(),state=random();const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier)),challenge=btoa(String.fromCharCode(...new Uint8Array(digest))).split('+').join('-').split('/').join('_').replace(/=+$/,'');sessionStorage.setItem(PENDING,JSON.stringify({client,verifier,state,at:Date.now()}));localStorage.setItem(CLIENT,client);const params=new URLSearchParams({client_id:client,response_type:'code',redirect_uri:redirect,scope:'playlist-read-private playlist-read-collaborative',state,code_challenge_method:'S256',code_challenge:challenge});location.assign('https://accounts.spotify.com/authorize?'+params)}catch(error){$('spotify-setup').close();status(error.message)}};
$('spotify-disconnect').onclick=()=>{auth=null;searchVersion++;sessionStorage.removeItem(SESSION);sessionStorage.removeItem(PENDING);$('account-playlists').replaceChildren();$('catalog-results').replaceChildren();$('playlists-more').hidden=true;controls();status('Disconnected on this tab. You can revoke app access in your Spotify account settings.')};
$('catalog-form').onsubmit=async event=>{event.preventDefault();const version=++searchVersion,query=$('catalog-query').value.trim(),type=$('catalog-type').value;if(!query)return;$('catalog-search').disabled=true;try{const data=await api('search?'+new URLSearchParams({q:query,type,limit:'10'}));if(version!==searchVersion)return;const list=data[type+'s']?.items||[];$('catalog-results').replaceChildren();rows($('catalog-results'),list);status(list.length?'Select a result to load it in the player.':'No matches found.')}catch(error){status(error.message)}finally{$('catalog-search').disabled=!auth}};
$('playlists-refresh').onclick=()=>playlists();$('playlists-more').onclick=()=>playlists(true);
controls();
const params=new URLSearchParams(location.search);if(params.has('code')||params.has('error')){const code=params.get('code'),state=params.get('state'),denied=params.get('error');history.replaceState(null,'',location.pathname);try{const pending=JSON.parse(sessionStorage.getItem(PENDING)||'null');sessionStorage.removeItem(PENDING);if(!pending||state!==pending.state||Date.now()-pending.at>600000)throw Error('Spotify return could not be verified. Connect again from this tab.');if(denied)throw Error('Spotify authorization was cancelled.');store(await tokenRequest({grant_type:'authorization_code',code,redirect_uri:redirect,client_id:pending.client,code_verifier:pending.verifier}),pending.client);await playlists()}catch(error){status(error.message)}}else if(auth)playlists();
